VILLAGE = {
'en': ('A village shaped by water, work and solidarity','Barqa is a living community in the northern Bekaa, on the eastern slopes of Mount Lebanon. Its story belongs to its residents as well as to the priest they remember.', [('The landscape','Association Malte Liban places Barqa above the Bekaa plain on Mount Lebanon’s eastern flank. The mountain setting helps explain the importance of collecting winter water.','https://malte-liban.org/centre-de-barqa/','Association Malte Liban'),('Water becomes an orchard','OSAD’s 2008 project account describes residents building rainwater reservoirs and bringing dry land into cultivation with apples, cherries and almonds. This is a story of local collective work.','https://www.osad.org/mprjcts/','OSAD · 2008'),('A legacy that keeps evolving','Anera reported in 2012 on its work with the YMCA in Barqa-Rabiaa: irrigation improvements, farmer training and tailored watering schedules. These later projects document continuing community development.','https://www.anera.org/stories/managing-scarce-water-lebanons-bekaa-valley/','Anera · 2012'),('People carry the story forward','Maria Chakhtoura’s 2010 report followed the village’s educational, social and environmental initiatives. Read it as a portrait of Barqa at that time, rather than a current visitor directory.','https://www.lorientlejour.com/article/673107/Barqa_ou_la_vengeance__par_le_developpement.html','L’Orient-Le Jour · 2010')]),
'fr': ('Un village façonné par l’eau, le travail et la solidarité','Barqa est une communauté vivante du nord de la Békaa, sur le versant oriental du Mont-Liban. Son histoire appartient à ses habitants autant qu’au prêtre dont ils gardent la mémoire.', [('Le paysage','L’Association Malte Liban situe Barqa sur le flanc oriental du Mont-Liban, au-dessus de la plaine de la Békaa. Ce cadre montagneux éclaire l’importance de recueillir les eaux d’hiver.','https://malte-liban.org/centre-de-barqa/','Association Malte Liban'),('De l’eau aux vergers','Le récit publié par OSAD en 2008 décrit des habitants construisant des réservoirs et cultivant des pommes, des cerises et des amandes sur des terres arides : une œuvre collective locale.','https://www.osad.org/mprjcts/','OSAD · 2008'),('Un héritage qui évolue','En 2012, Anera a présenté son travail avec le YMCA à Barqa-Rabiaa : irrigation améliorée, formation et calendriers d’arrosage adaptés. Ces projets ultérieurs témoignent du développement de la communauté.','https://www.anera.org/stories/managing-scarce-water-lebanons-bekaa-valley/','Anera · 2012'),('Les habitants font vivre l’histoire','Le reportage de Maria Chakhtoura de 2010 suit les initiatives éducatives, sociales et écologiques du village. Il s’agit d’un portrait historique, plutôt que d’un guide actuel de visite.','https://www.lorientlejour.com/article/673107/Barqa_ou_la_vengeance__par_le_developpement.html','L’Orient-Le Jour · 2010')]),
'ar': ('بلدة تصوغها المياه والعمل والتضامن','برقا مجتمع حيّ في البقاع الشمالي، على السفح الشرقي لجبل لبنان. حكايتها لأهلها كما هي للكاهن الذي يحتفظون بذكراه.', [('المكان والطبيعة','تصف جمعية مالطا لبنان برقا بأنها على السفح الشرقي لجبل لبنان، مشرفة على سهل البقاع. يساعد هذا الموقع الجبلي على فهم أهمية تجميع مياه الشتاء.','https://malte-liban.org/centre-de-barqa/','جمعية مالطا لبنان'),('من المياه إلى البساتين','يروي تقرير OSAD الصادر عام 2008 كيف تعاون الأهالي على بناء خزّانات لمياه الأمطار وتحويل أراضٍ جافة إلى بساتين تفاح وكرز ولوز. إنها حكاية عمل محلي مشترك.','https://www.osad.org/mprjcts/','OSAD · 2008'),('إرث يستمرّ ويتطوّر','وثّقت أنيرا عام 2012 عملها مع جمعية الشبان المسيحية في برقا–ربيعا: تحسين الري وتدريب المزارعين وتنظيم مواعيد السقاية. توثّق هذه المشاريع اللاحقة استمرار التنمية المجتمعيّة.','https://www.anera.org/stories/managing-scarce-water-lebanons-bekaa-valley/','أنيرا · 2012'),('الأهالي يحملون الحكاية','تابع تحقيق ماريا شختورة عام 2010 مبادرات البلدة التعليميّة والاجتماعيّة والبيئيّة. نقرأه بوصفه صورة للبلدة في ذلك الوقت، لا دليل زيارة محدّثًا.','https://www.lorientlejour.com/article/673107/Barqa_ou_la_vengeance__par_le_developpement.html','لوريان لوجور · 2010')])}

def install(g):
    g['PAGES'] = (*g['PAGES'], 'discover', 'prayer', 'media')
    for lang in g['LOCALES']:
        t=L[lang]; c=g['CONTENT'][lang]
        g['NAV'][lang].extend([t['discover'],t['prayer'],t['media']])
        title,summary,sections=VILLAGE[lang]
        cards=''.join(f"<section class='village-chapter'><span class='chapter-number'>0{i+1}</span><div><h2>{h}</h2><p>{p}</p><a href='{url}' target='_blank' rel='noopener noreferrer'>{src} →</a></div></section>" for i,(h,p,url,src) in enumerate(sections))
        c['discover']={'eyebrow':'BARQA · برقا · BÉKAA','title':title,'summary':summary,'body':f"<div class='village-map'><div class='contours' aria-hidden='true'></div><p class='eyebrow'>LEBANON · لبنان</p><h2>Barqa / برقا</h2><p>Baalbek-Hermel · Bekaa</p><a class='button-link' href='https://www.google.com/maps/search/?api=1&amp;query=Barqa+Lebanon' target='_blank' rel='noopener noreferrer'>Barqa · Google Maps →</a></div><div class='village-chapters'>{cards}</div><a class='button-link' href='barqa.html'>{g['NAV'][lang][2]} →</a>"}
        prayer=f"<div class='prayer-layout'><section class='prayer-card'><span class='cross-mark' aria-hidden='true'>✝</span><p class='eyebrow'>{t['quiet']}</p><h2>{t['reflection']}</h2><p id='prayer-text'>{t['pray']}</p><small>{t['prayernote']}</small><div class='silence-ring' aria-hidden='true'></div><p id='timer-readout' aria-live='polite'>01:00</p><button id='silence-button' class='button-link'>{t['start']}</button></section><section class='intention-card'><p class='eyebrow'>{t['prompt']}</p><label for='intention'>{t['note']}</label><textarea id='intention' rows='7' maxlength='3000'></textarea><p class='privacy-note'>{t['privacy']}</p><div class='map-actions'><button id='save-intention' class='button-link'>{t['save']}</button><button id='clear-intention' class='quiet-button'>{t['clear']}</button></div><p id='note-status' role='status'></p></section></div>"
        c['prayer']={'eyebrow':t['light'],'title':t['quiet'],'summary':t['prompt'],'body':prayer}
        media_items=[('AUDIO · NL','Ignis · Rick Timmermans',{'en':'A Dutch-language Jesuit audio documentary draws on letters and recollections, including those of his friend Piet van Breemen. Listen on the publisher’s page.','fr':'Ce documentaire audio en néerlandais s’appuie sur des lettres et des souvenirs, dont ceux de son ami Piet van Breemen. Écoutez-le chez l’éditeur.','ar':'وثائقي صوتي يسوعي باللغة الهولندية يستند إلى رسائل وذكريات، منها شهادة صديقه بيت فان بريمن. استمع عبر موقع الناشر.'}[lang],'https://igniswebmagazine.nl/kerk/audio-documentaire-nico-kluiters/'),('REPORTAGE · FR','Barqa · 2010',sections[3][1],sections[3][2]),('PHOTOGRAPHY · AR / EN / FR',t['gallery'],t['mediaintro'],'archive.html')]
        media_body="<div class='media-grid'>"+''.join(f"<a class='media-card' href='{u}'><span class='eyebrow'>{k}</span><span class='media-icon' aria-hidden='true'>{'▶' if i==0 else ('≋' if i==1 else '▧')}</span><h2>{h}</h2><p>{p}</p><span class='text-link'>{t['listen']} →</span></a>" for i,(k,h,p,u) in enumerate(media_items))+f"</div><section class='community-panel'><h2>{t['contribute']}</h2><p>{t['contributenote']}</p><a class='button-link' href='https://github.com/ccg-cyber/nicolas-kluiters-living-legacy/issues/new?title=Archive+contribution&amp;body=Source%20or%20date%3A%0A%0AMemory%20or%20correction%3A%0A%0APhoto%20rights%20and%20credit%3A'>{t['submit']} →</a></section>"
        c['media']={'eyebrow':t['listen'],'title':t['media'],'summary':t['mediaintro'],'body':media_body}
        c['index']['title']=t['intro']; c['index']['summary']=t['deck']
        c['index']['eyebrow']=t['light']
        c['index']['body']=f"<div class='experience-strip'><a href='discover.html'><span>01 / BARQA</span><h2>{t['discover']}</h2></a><a href='prayer.html'><span>02 / SPIRIT</span><h2>{t['prayer']}</h2></a><a href='media.html'><span>03 / STORIES</span><h2>{t['media']}</h2></a></div>"+c['index']['body']
        # Add the new firsthand development accounts to the existing source register.
        c['sources']['body'] += "<section class='source-grid'>"+''.join(f"<article><span class='source-type'>{src}</span><h3>{h}</h3><p>{p}</p><a href='{url}'>{src} →</a></article>" for h,p,url,src in sections[1:])+"</section>"
    original=g['render']
    def render(lang,slug):
        t=L[lang]; html=original(lang,slug); prefix='assets/' if lang=='ar' else '../assets/'
        tools=f"<div class='page-tools'><button data-open-search>{t['search']} <span aria-hidden='true'>⌕</span></button><button data-share>{t['share']} <span aria-hidden='true'>→</span></button><span class='share-status' role='status'></span></div>"
        html=html.replace("<main id='main'>",f"<main id='main'>{tools}")
        html=html.replace("<body>",f"<body class='page-{slug}'>")
        html=html.replace("<nav class='main-nav'",f"<button class='menu-toggle' aria-expanded='false' aria-controls='primary-navigation'>{g['TEXT'][lang]['menu']} +</button><nav id='primary-navigation' class='main-nav'")
        # Native sharing and direct share links work without any social account owned by this project.
        from urllib.parse import quote
        url=g['BASE']+g['locale_path'](lang,slug)
        social=f"<section class='social-band'><div><p class='eyebrow'>{t['shareheading']}</p><h2>{t['sharetext']}</h2></div><div class='share-links'><a href='https://wa.me/?text={quote(t['intro']+' '+url)}' target='_blank' rel='noopener noreferrer'>WhatsApp</a><a href='https://www.facebook.com/sharer/sharer.php?u={quote(url,safe='')}' target='_blank' rel='noopener noreferrer'>Facebook</a><button data-share>{t['share']}</button></div></section>"
        q=QUIZ[lang]
        if slug in ('discover','index'):
            challenge=f"<section class='discovery-game'><div><p class='eyebrow'>01 · 02 · 03 · 04 · 05</p><h2>{q['title']}</h2><p>{q['intro']}</p></div><div id='quiz-stage'><button id='quiz-start' class='button-link'>{q['start']}</button></div></section>"
            html=html.replace('</main>',challenge+'</main>')
        html=html.replace('</main>',social+'</main>')
        dialog=f"<dialog id='search-dialog'><div class='dialog-top'><label for='site-search'>{t['search']}</label><button data-close-search>{t['close']} ×</button></div><input id='site-search' type='search' autocomplete='off'><div id='search-results' aria-live='polite'></div></dialog><dialog id='photo-dialog'><div class='dialog-top'><span id='photo-count'></span><button id='close-photo'>{t['close']} ×</button></div><img id='large-photo' alt=''><p id='large-caption'></p><div class='viewer-controls'><button id='previous-photo'>{t['previous']}</button><a id='photo-source' target='_blank' rel='noopener noreferrer'>{t['source']}</a><button id='next-photo'>{t['next']}</button></div></dialog>"
        records=[{'title':g['CONTENT'][lang][p]['title'],'text':g['CONTENT'][lang][p]['summary'],'href':'index.html' if p=='index' else p+'.html'} for p in g['PAGES']]
        data=json.dumps({'labels':t,'pages':records,'quiz':QUIZ[lang]},ensure_ascii=False).replace('<','\\u003c')
        html=html.replace('</body>',f"{dialog}<script id='site-data' type='application/json'>{data}</script><script src='{prefix}site.js' defer></script></body>")
        return html
    g['render']=render
